          "sampleSolution": "/* This program contains 2 parts: (1) and (2)\n   YOUR TASK IS TO COMPLETE THE PART  (2)  ONLY\n */\n//(1)==============================================================\nimport java.util.*;\nimport java.io.*;\n\npublic class MyList {\n  Node head,tail;\n  MyList() {head=tail=null;}\n  boolean isEmpty() {\n    return(head==null);\n   }\n  void clear() {head=tail=null;}\n\n  void fvisit(Node p, RandomAccessFile f) throws Exception {\n    if(p != null) f.writeBytes(p.info + \" \");\n   }\n\n  void ftraverse(RandomAccessFile f) throws Exception {\n    Node p = head;\n    while(p!=null) {\n       fvisit(p,f); // You will use this statement to write information of the node p to the file\n       p=p.next;\n      }\n    f.writeBytes(\"\\r\\n\");\n   }\n\n  void loadData(int k) { //do not edit this function\n    String [] a = Lib.readLineToStrArray(\"data.txt\", k);\n    int [] b = Lib.readLineToIntArray(\"data.txt\", k+1);\n    int [] c = Lib.readLineToIntArray(\"data.txt\", k+2);\n    int n = a.length;\n    for(int i=0;i<n;i++) addLast(a[i],b[i],c[i]);\n   }\n\n//===========================================================================\n//(2)===YOU CAN EDIT OR EVEN ADD NEW FUNCTIONS IN THE FOLLOWING PART========\n//===========================================================================\n/* \n   Khong su dung tieng Viet co dau de viet ghi chu.\n   Neu dung khi chay truc tiep se bao loi va nhan 0 diem\n*/\n  void addLast(String xPlace, int xSong, int xWing) {\n    //You should write here appropriate statements to complete this function.\n    if (xPlace.charAt(0) == 'A') return;\n    Canary c = new Canary(xPlace, xSong, xWing);\n    Node p = new Node(c);\n    if (head == null) {\n      head = tail = p;\n    } else {\n      tail.next = p;\n      tail = p;\n    }\n   }\n\n  //You do not need to edit this function. Your task is to complete the addLast function above only.\n  void f1() throws Exception {\n     clear();\n     loadData(1);\n     String fname = \"f1.txt\";\n     File g123 = new File(fname);\n     if(g123.exists()) g123.delete();\n     RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \n     ftraverse(f);\n     f.close();\n    }  \n\n//==================================================================\n  void f2() throws Exception {\n     clear();\n     loadData(5);\n     String fname = \"f2.txt\";\n     File g123 = new File(fname);\n     if(g123.exists()) g123.delete();\n     RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \n     ftraverse(f);\n     Canary x, y, z;\n     x = new Canary(\"X\",1,2);\n     y = new Canary(\"Y\",2,3);\n     z = new Canary(\"Z\",3,4);\n     //------------------------------------------------------------------------------------\n     /*You must keep statements pre-given in this function.\n       Your task is to insert statements here, just after this comment,\n       to complete the question in the exam paper.*/\n     insertAtPosition(x, 2);\n     insertAtPosition(y, 5);\n     insertAtPosition(z, 6);\n    //------------------------------------------------------------------------------------\n     ftraverse(f);\n     f.close();\n    }  \n\n  void insertAtPosition(Canary c, int pos) {\n    Node p = new Node(c);\n    if (pos == 0) {\n      p.next = head;\n      head = p;\n      if (tail == null) tail = p;\n      return;\n    }\n    Node prev = head;\n    for (int i = 0; i < pos - 1; i++) prev = prev.next;\n    p.next = prev.next;\n    prev.next = p;\n    if (p.next == null) tail = p;\n   }\n\n//==================================================================\n\n  void f3() throws Exception {\n    clear();\n    loadData(9);\n    String fname = \"f3.txt\";\n    File g123 = new File(fname);\n    if(g123.exists()) g123.delete();\n    RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \n    ftraverse(f);\n    //------------------------------------------------------------------------------------\n     /*You must keep statements pre-given in this function.\n       Your task is to insert statements here, just after this comment,\n       to complete the question in the exam paper.*/\n    Node p = head;\n    while (p != null && !p.info.place.equals(\"E\")) p = p.next;\n    int k = (p != null) ? p.info.wing : Integer.MIN_VALUE;\n    Node cur = head, prev = null;\n    while (cur != null) {\n      if (cur.info.wing < k) {\n        if (prev == null) {\n          head = cur.next;\n        } else {\n          prev.next = cur.next;\n        }\n        if (cur == tail) tail = prev;\n        cur = cur.next;\n      } else {\n        prev = cur;\n        cur = cur.next;\n      }\n    }\n    //------------------------------------------------------------------------------------\n    ftraverse(f);\n    f.close();\n  }   \n\n//==================================================================\n  void f4() throws Exception {\n    clear();\n    loadData(13);\n    String fname = \"f4.txt\";\n    File g123 = new File(fname);\n    if(g123.exists()) g123.delete();\n    RandomAccessFile  f = new RandomAccessFile(fname, \"rw\"); \n    ftraverse(f);\n    //------------------------------------------------------------------------------------\n     /*You must keep statements pre-given in this function.\n       Your task is to insert statements here, just after this comment,\n       to complete the question in the exam paper.*/\n    Node p = head;\n    while (p != null && !p.info.place.equals(\"E\")) p = p.next;\n    Node q = p;\n    while (q != null && !q.info.place.equals(\"K\")) q = q.next;\n    if (p != null && q != null) {\n      java.util.ArrayList<Node> segNodes = new java.util.ArrayList<Node>();\n      Node t = p;\n      while (true) {\n        segNodes.add(t);\n        if (t == q) break;\n        t = t.next;\n      }\n      java.util.ArrayList<Canary> vals = new java.util.ArrayList<Canary>();\n      for (Node n : segNodes) vals.add(n.info);\n      vals.sort((a, b) -> a.wing - b.wing);\n      for (int i = 0; i < segNodes.size(); i++) segNodes.get(i).info = vals.get(i);\n    }\n    //------------------------------------------------------------------------------------\n    ftraverse(f);\n    f.close();\n   }\n\n }\n\n",
